from author import C,S,P,V
c=C('向量与线性组合')
S(c,'课程知识总览',[
 P('同学们好，欢迎来到一小时学习线性代数。本课从没有学过线性代数的大学生出发，只用到熟悉的加减乘除、简单方程和坐标。我们先把一串数字画成箭头，再看矩阵怎样改变这些箭头。行列式告诉我们面积怎样变化，秩帮助判断还剩多少个独立方向。先看见发生了什么，再给它一个正式名字。',V('cover'),[],['向量与矩阵','行列式、逆矩阵与秩','方程组、特征值与二次型'],0),
 P('你给出的资料共有六章，我们会按理解所需要的先后顺序串成十节。每节先演示，再解释计算，最后留一道小题。遇到新公式，先认清每个符号表示什么，再看它解决哪一种问题。图形主要画在二维和三维中，方便观察；涉及一般维数的结论，会把条件写清楚。重要计算和完整知识点索引也会放进配套讲义。',V('cover'),[],['从图形进入计算','每章一道独立练习','原文件知识点逐项建立索引'],0)],['导学'])
S(c,'一串数字怎样变成箭头',[
 P('先看从原点出发的蓝色箭头。它向右走两格，再向上走一格，所以可以用两个数，二和一，记录它的位置。这两个数的顺序有意义，交换以后会指向另一个位置。我们把这样的有序数字称为向量，这里是二维向量。箭头可以平移着画，但在本课讨论中，重点是它的方向和长度。',V('vectors',u=[2,1],phase='draw'),[r'\mathbf{u}=(2,1)^T'],['两个分量按顺序排列','箭头先统一从原点出发'],7),
 P('现在把箭头转到另一处，末端坐标变了，表示的向量也跟着变。三维向量需要三个数，更多维时就用更多分量，未必还能直接画成一支空间箭头。上标这个小写的转置符号，表示把横着写的数字改成竖着排。图形是帮助理解的模型，真正计算时始终看各个分量，不能只凭画面估计。',V('vectors',u=[1,2],phase='rotate',start=[2,1]),[r'\mathbb{R}^n',r'\mathbf{x}=(x_1,\ldots,x_n)^T'],['二维、三维再推广到 n 维','坐标是精确数据，图形辅助理解'],7)],['3.1-向量与维数'])
S(c,'向量相加与数乘',[
 P('现在把橙色箭头平移到蓝色箭头的末端，方向和长度都保持不变。再从原点连到最后的末端，这支绿色箭头就是两者的和。蓝色是二和一，橙色是一和二，所以结果是三和三。计算时对应位置分别相加，图上则是把两段位移接起来，这就是同一件事的两种表示。',V('vectors',u=[2,1],v=[1,2],phase='add'),[r'(2,1)^T+(1,2)^T=(3,3)^T'],['同位置分量相加','首尾相接得到总位移'],8),
 P('再看数乘。把蓝色箭头乘二，各个分量都乘二，方向不变、长度加倍。乘负一，方向反过来；乘零，结果回到原点，是零向量。数乘里的数可以是负数，也可以是小数。向量相加和数乘是后面所有内容的基本动作，看到复杂公式时，不妨先问它是不是在把这两件简单事情组合起来。',V('vectors',u=[2,1],phase='scale',factor=-1),[r'k(x,y)^T=(kx,ky)^T',r'0\mathbf{u}=\mathbf{0}'],['正倍数伸缩，负倍数还反向','零向量不提供方向'],10)],['3.1-向量运算'])
S(c,'线性组合能到达哪些地方',[
 P('让两个箭头分别乘上可以调整的数，再相加，就得到线性组合。这里蓝色朝右、橙色朝上，调节两个系数，绿色末端可以到达平面上任意一点。系数并不要求是正数，因此也能向左、向下。所有能够这样到达的向量构成它们张成的范围，先把它理解成这组箭头的活动范围。',V('vectors',u=[1,0],v=[0,1],phase='span'),[r'\mathbf{b}=c_1\mathbf{u}+c_2\mathbf{v}'],['线性组合：数乘以后相加','系数可以为任意实数','两条不同方向可以铺满平面'],14),
 P('现在把橙色箭头改到与蓝色同一直线上。无论怎样调节系数，总结果仍在这条线上，无法跑到整张平面。两个名字不一定提供两个独立方向。若一组向量中的每个向量都能由另一组表示，反过来也成立，两组的活动范围相同，就称向量组等价。它们的向量个数可以不同，不要把等价误解成逐个完全一样。',V('vectors',u=[1,1],v=[2,2],phase='span'),[r'\operatorname{span}(S)=\operatorname{span}(T)'],['共线组合只能沿直线移动','向量组等价看张成范围','向量个数不必相同'],14)],['3.1-线性组合与线性表示','3.1-向量组等价'])
S(c,'方程组也能用向量来读',[
 P('观察这两条方程。第一条说横坐标怎样凑出四，第二条说纵坐标怎样凑出五。把相同未知数前面的系数竖着收集起来，就得到两支列向量。求解方程组，其实是在问：第一支拿多少倍，第二支拿多少倍，才能拼出右边这个目标向量。未知数现在有了很具体的角色，它们就是组合系数。',V('vectors',u=[1,2],v=[1,1],phase='target',target=[4,5]),[r'x+y=4',r'2x+y=5',r'x(1,2)^T+y(1,1)^T=(4,5)^T'],['按列收集同一未知数的系数','未知数就是组合系数'],8),
 P('本例取第一支的一倍、第二支的三倍，正好到达四和五，因此解是一和三。这里先理解问题，不急着背求解流程。接下来矩阵会把这些列向量收在同一个表格里，消元会帮助我们系统地找系数。向量、矩阵和方程组不是互相独立的三套课程，而是从不同角度描述同一个组合问题。',V('vectors',u=[1,2],v=[1,1],phase='combine',coeff=[1,3]),[r'x=1,\quad y=3'],['检查组合是否到达目标','把方程与图形联系起来'],8)],['3.1-线性方程组向量形式'])
S(c,'练习：两个箭头够不够',[
 P('蓝色向量是一和二，橙色向量是二和四。能不能只靠它们的数乘与相加，得到横坐标一、纵坐标零的目标？请先看两支箭头的关系，再看目标是否在同一条直线上。不要因为手里有两个向量，就直接断言能到达整个二维平面。现在独立思考四秒。',V('vectors',u=[1,2],v=[2,4],phase='target',target=[1,0]),[r'c_1(1,2)^T+c_2(2,4)^T=(1,0)^T\ ?'],['先看两个方向是否重复','目标是否落在同一直线上'],0)],['3.1-练习'],kind='question',answer='不能；两向量共线，任意组合满足 y=2x。')
S(c,'答案：数量不等于方向数',[
 P('不能。橙色恰好是蓝色的两倍，它们的任意组合都能写成蓝色的某个倍数。因此横坐标与纵坐标一直满足，纵坐标等于横坐标的两倍。目标一和零不满足这个关系，所以到不了。图上看到目标离开了这条线，计算上看到坐标关系不成立，两种判断相互印证。',V('vectors',u=[1,2],v=[2,4],phase='span',target=[1,0]),[r'c_1\mathbf{u}+c_2(2\mathbf{u})=(c_1+2c_2)\mathbf{u}',r'y=2x'],['两支箭头只提供一个方向','目标不在它们张成的直线上'],10),
 P('这个小题已经碰到了后面的线性相关和秩。我们稍后再给出严格定义，现在先留下一个直观印象：重要的是提供了多少个不可替代的方向，而不是写了多少个名字。遇到一个新的抽象词，可以先寻找它在这幅图里对应什么。接下来把向量整齐排成矩阵，看看一个数字表格怎样控制整张坐标网格。',V('vectors',u=[1,2],v=[2,4],phase='static'),[r'\text{方向数：1}'],['先建立图像，再记正式术语','下一步：用矩阵组织向量'],0)],['3.1-练习答案'])

c=C('矩阵与线性变换')
S(c,'矩阵是有尺寸的数字表',[
 P('矩阵先是一张按行和列排列的数字表。这里有两行三列，尺寸就写成二乘三，先行数、后列数。每个位置的数字叫元素，通常用两个下标说明在哪一行、哪一列。矩阵本身不是一个数，也不能因为外形像表格，就把它的运算理解成任意逐格操作。先确认尺寸，是开始计算前很有用的一步。',V('matrix',A=[[1,2,3],[4,5,6]],highlight=[0,1]),[r'A=(a_{ij})_{m\times n}'],['先行数，后列数','a 的两个下标指明行列位置'],6),
 P('行数和列数相同，叫方阵。全是零的叫零矩阵，主对角线全是一、其他位置为零的叫单位矩阵，常用字母 I 表示。对角矩阵只允许主对角线上非零，三角矩阵则让主对角线的一侧为零。它们有结构上的规律，后面能简化计算；但方阵、单位矩阵和对角矩阵不是可以随便互换的名字。',V('matrix',A=[[1,0,0],[0,1,0],[0,0,1]],highlight='diagonal'),[r'I\mathbf{x}=\mathbf{x}'],['零矩阵、方阵、对角与三角矩阵','单位矩阵表示保持不变'],6)],['2.1-矩阵概念与特殊矩阵'])
S(c,'矩阵的列决定网格怎样变',[
 P('现在看一个二阶方阵对平面的作用。第一列告诉我们向右的一小步会移到哪里，第二列告诉我们向上的一小步会移到哪里。这里第一列是二和零，第二列是一和一，于是蓝色基准箭头被拉长，橙色基准箭头向右倾斜。整个网格跟着变，平行直线仍保持平行，原点仍在原点。',V('transform',A=[[2,1],[0,1]]),[r'A=\left[\,\mathbf{a}_1\ \mathbf{a}_2\,\right]',r'A(x,y)^T=x\mathbf{a}_1+y\mathbf{a}_2'],['两列给出两支基准箭头的新位置','任意向量按同样系数组合'],10),
 P('因为任意向量都能由这两支基准箭头组合，知道两列，就知道它会怎样移动。向量相加以后再变换，等于先分别变换再相加；倍数关系也保留，这就是线性变换的关键。我们画二维只是为了看清楚，矩阵还可以把三维输入变成二维输出。此时仍然按照列向量的组合计算，只是不能把它看成同一平面里的简单旋转。',V('transform',A=[[2,1],[0,1]],point=[1,2]),[r'A(\mathbf{u}+\mathbf{v})=A\mathbf{u}+A\mathbf{v}',r'A(k\mathbf{u})=kA\mathbf{u}'],['线性保持加法和数乘','矩阵可以连接不同维数'],10)],['2.1-矩阵的作用','2.2-矩阵与向量乘法'])
S(c,'加法、数乘与矩阵乘法',[
 P('同样尺寸的矩阵相加，只要对应位置相加。给矩阵乘一个数，就让每个元素都乘这个数。尺寸不同不能直接相加。请看高亮位置，它们始终在相同的行列位置配对。加法和数乘可以按熟悉的分配律来计算，但这还没有说明两张矩阵相乘应该怎样做，矩阵乘法需要另一条规则。',V('matrix',A=[[1,2],[0,1]],B=[[2,0],[1,3]],operation='add'),[r'(A+B)_{ij}=a_{ij}+b_{ij}',r'(kA)_{ij}=ka_{ij}'],['加法要求尺寸相同','数乘作用于每一个元素'],8),
 P('现在用左边的一行对右边的一列，对应位置相乘，再加起来。这个和填到结果的对应位置。左矩阵的列数，必须等于右矩阵的行数，才能一一配对。如果左边是二乘三、右边是三乘二，结果就是二乘二。与其背一句口诀，不如每次指出，选了哪一行、哪一列，最后把数填到哪里。',V('multiply',A=[[1,2,0],[0,1,1]],B=[[1,0],[2,1],[0,3]]),[r'(AB)_{ij}=\sum_k a_{ik}b_{kj}',r'(2\times3)(3\times2)\to2\times2'],['行乘列，乘积再相加','中间尺寸相同，保留外侧尺寸'],12)],['2.2-线性运算','2.2-乘法与运算律'])
S(c,'顺序、幂与矩阵多项式',[
 P('两次变换接着做，就对应矩阵乘法。这里先向右错切，再拉伸，和先拉伸、再错切，得到的网格不同。所以矩阵乘法通常不能交换顺序。写成 A 乘 B 作用在向量上时，向量先经过 B，再经过 A，从右往左读作用顺序。结合律允许重新加括号，分配律也成立，但不能因此擅自交换两个矩阵。',V('transform',A=[[2,2],[0,1]],B=[[2,1],[0,1]],phase='compare'),[r'AB\ne BA\ \text{一般成立}',r'(AB)\mathbf{x}=A(B\mathbf{x})'],['复合变换从右向左作用','可结合、可分配，通常不可交换'],12),
 P('同一个方阵反复相乘，可以写成幂。零次幂规定为同阶单位矩阵，正整数次幂按重复相乘理解。矩阵多项式则把常数项换成对应倍数的单位矩阵，例如 A 平方加二倍 A 再加 I。这里同一个 A 的幂可以按通常规则合并，但把两个不同矩阵的和平方，交叉项应写 A B 加 B A，不能默认合成二倍 A B。',V('matrix',A=[[1,1],[0,1]],operation='power'),[r'A^0=I',r'p(A)=A^2+2A+I',r'(A+B)^2=A^2+AB+BA+B^2'],['幂与多项式针对方阵','常数项对应常数乘单位矩阵'],8)],['2.2-方阵的幂','2.2-矩阵多项式'])
S(c,'转置与对称结构',[
 P('现在让矩阵沿主对角线翻过去，行就变成列，这个操作叫转置。原来二行三列，转置以后变成三行二列。转置两次会回来，加法和数乘也容易对应。但是乘积转置时，顺序要反过来，A B 的转置等于 B 的转置乘 A 的转置。把行和列的位置逐个追踪，比单独背一个反序更容易理解。',V('transpose',A=[[1,2,3],[4,5,6]]),[r'(A^T)^T=A',r'(AB)^T=B^TA^T'],['转置交换行与列','乘积转置需要反序'],10),
 P('如果方阵转置以后不变，叫对称矩阵，主对角线两侧互相对应。若转置以后等于原来的相反数，叫反对称矩阵；在实数范围内，它的主对角元素都是零。任意实方阵都能拆成对称部分和反对称部分，画面给出了各取一半的公式。请注意，这里比较的是转置前后的元素关系，不是看数字排列是否让人觉得美观。',V('matrix',A=[[2,1],[1,3]],B=[[0,2],[-2,0]],operation='symmetry'),[r'S^T=S,\quad K^T=-K',r'A=\frac{A+A^T}{2}+\frac{A-A^T}{2}'],['对称矩阵在对角线两侧相等','实反对称矩阵对角元素为零'],6)],['2.2-转置及运算律','2.2-对称与反对称矩阵'])
S(c,'分块计算仍然要检查尺寸',[
 P('大矩阵可以按行列切成几个小块，用颜色把它们分开，这叫分块矩阵。每个块本身仍然是矩阵，不是一个随便的数字。分块加法要求切法相容，分块乘法则要求参与配对的内部尺寸也相容。右边公式的形状像普通二阶乘法，但每一项都是一张矩阵的乘积，顺序仍然不能乱。',V('matrix',A=[[1,0,2,0],[0,1,0,2],[3,0,1,0],[0,3,0,1]],operation='blocks'),[r'(AB)_{11}=A_{11}B_{11}+A_{12}B_{21}'],['按行列分块，块也有尺寸','分块乘法保留原来的作用顺序'],10),
 P('分块的价值，是把有规律的大问题拆成小问题。比如某些块全为零，就能少算很多项。它并没有创造一套可以忽略尺寸的新运算。对于两个同阶方阵，行列式还满足乘积的行列式等于各自行列式之积；这个性质会在后面的面积与可逆性中连接起来。先把矩阵运算看清，接下来再给方阵配上这个特别的数。',V('matrix',A=[[1,0,2,0],[0,1,0,2],[0,0,3,0],[0,0,0,3]],operation='blocks'),[r'\det(AB)=\det(A)\det(B)'],['零块可以简化计算','行列式乘法律要求同阶方阵'],8)],['2.2-分块运算','2.2-方阵行列式及运算律'])
S(c,'练习：哪两个矩阵能够相乘',[
 P('已知 A 是二乘三矩阵，B 是三乘二矩阵。A 乘 B 和 B 乘 A，哪些有意义，各是什么尺寸？再判断它们能不能因为使用了同样两张矩阵，就直接认定相等。先圈出中间两个尺寸，看能否配对；再留下外侧尺寸，作为结果的行数和列数。请独立思考。',V('matrix',A=[[1,2,3],[4,5,6]],B=[[1,0],[0,1],[1,1]],operation='dimensions'),[r'A_{2\times3},\quad B_{3\times2}',r'AB\ ?\quad BA\ ?'],['先核对相邻的两个尺寸','再确定结果的外侧尺寸'],0)],['2.2-练习'],kind='question',answer='都能相乘；AB为2×2，BA为3×3，尺寸不同，不能相等。')
S(c,'答案：能算不代表结果相同',[
 P('两种顺序都能相乘，但结果尺寸不同。A 乘 B 的中间两个三配对，结果二乘二；B 乘 A 的中间两个二配对，结果三乘三。这两张结果连尺寸都不同，因此不能相等。很多矩阵错误不需要算到最后，只检查尺寸，就已经能发现。这个习惯在以后看复杂公式时尤其有用。',V('multiply',A=[[1,2,3],[4,5,6]],B=[[1,0],[0,1],[1,1]]),[r'AB\in\mathbb{R}^{2\times2}',r'BA\in\mathbb{R}^{3\times3}'],['两种顺序均可计算','结果尺寸分别是二阶与三阶'],10),
 P('即使两张矩阵同阶、两个乘积尺寸相同，也只能说它们有资格比较，仍不能自动交换。请把尺寸检查和数值计算分开：先判断运算有没有意义，再按规则算。到这里，矩阵已经从一张数字表，变成了描述组合和变换的工具。下一章研究行列式，用一个数概括方阵对面积、体积和信息压缩的重要影响。',V('transform',A=[[2,2],[0,1]],B=[[2,1],[0,1]],phase='compare'),[r'AB=BA\ \text{需要额外条件}'],['同阶也不保证交换','先检查意义，再进行计算'],8)],['2.2-练习答案'])
